    FROM reviews r
    JOIN users u ON r.user_id = u.id
    JOIN books b ON r.book_id = b.id
    WHERE r.book_id = ?
    ORDER BY ${sort}
  `, [bookId]) as unknown as ReviewWithDetails[];
}

// Count of reviews per star value, always returning all five buckets.
